#include <cstdio>
#include <cstring>
#include <algorithm>
#include <vector>

const int MAX_N = 50;
const int MAX_M = 50;
const int MAX_K = 50;
const int MAX_T = MAX_N + MAX_K + 1;
const int MAX_NODES = MAX_N * MAX_T + 1;
const int MAX_EDGES = MAX_K + (MAX_M * 2 * MAX_K + MAX_N) * (MAX_T - 1);
const int INF = 0x3f3f3f3f;

struct Edge {
    int u, v, uv, cost, cap;
};

int edge_cnt;
int uu[MAX_EDGES], vv[MAX_EDGES], uv[MAX_EDGES], cost[MAX_EDGES], ccost[MAX_EDGES];
int cc[MAX_EDGES * 2];

std::vector<int> adj_list[MAX_NODES];

void add_edge(int u, int v, int cap, int cos) {
    int h = edge_cnt++;
    uu[h] = u; vv[h] = v; uv[h] = u ^ v;
    cost[h] = cos;
    cc[h * 2] = cap;
    cc[h * 2 + 1] = 0;
    adj_list[u].push_back(h * 2);
    adj_list[v].push_back(h * 2 + 1);
}

int pi[MAX_NODES], kk[MAX_NODES], bb[MAX_NODES];
int pq[1 + MAX_NODES], iq[MAX_NODES], pq_cnt;

#define LT(u, v) (pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]))

int i2(int i) {
    return (i *= 2) > pq_cnt ? 0 : i < pq_cnt && LT(pq[i + 1], pq[i]) ? i + 1 : i;
}

void pq_up(int u) {
    int i, j;
    for (i = iq[u]; (j = i / 2) && LT(u, pq[j]); i = j)
        pq[iq[pq[j]] = i] = pq[j];
    pq[iq[u] = i] = u;
}

void pq_dn(int u) {
    int i, j;
    for (i = iq[u]; (j = i2(i)) && LT(pq[j], u); i = j)
        pq[iq[pq[j]] = i] = pq[j];
    pq[iq[u] = i] = u;
}

void pq_add(int u) {
    iq[u] = ++pq_cnt;
    pq_up(u);
}

int pq_pop() {
    int u = pq[1], v = pq[pq_cnt--];
    iq[v] = 1;
    pq_dn(v);
    return u;
}

void dijkstra(int s) {
    memset(pi, 0x3f, sizeof(int) * MAX_NODES);
    pi[s] = 0;
    kk[s] = 0;
    pq_add(s);
    while (pq_cnt) {
        int u = pq_pop();
        int v;
        for (int he : adj_list[u]) {
            if (cc[he] == 0) continue;
            int h = he / 2;
            int p = pi[u] + ((he & 1) == 0 ? ccost[h] : -ccost[h]);
            v = u ^ uv[h];
            if (pi[v] == INF) {
                pi[v] = p;
                kk[v] = kk[u] + 1;
                bb[v] = he;
                pq_add(v);
            } else if (pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                pi[v] = p;
                kk[v] = kk[u] + 1;
                bb[v] = he;
                pq_up(v);
            }
        }
    }
}

void push(int s, int t) {
    int u, h, he;
    for (u = t; u != s; u ^= uv[h]) {
        he = bb[u];
        h = he / 2;
        cc[he]--;
        cc[he ^ 1]++;
    }
}

int edmonds_karp(int s, int t) {
    memcpy(ccost, cost, sizeof(int) * edge_cnt);
    while (true) {
        dijkstra(s);
        if (pi[t] == INF) break;
        push(s, t);
        for (int h = 0; h < edge_cnt; h++) {
            int u = uu[h], v = vv[h];
            if (pi[u] != INF && pi[v] != INF)
                ccost[h] += pi[u] - pi[v];
        }
    }
    int total_cost = 0;
    for (int h = 0; h < edge_cnt; h++)
        total_cost += cost[h] * cc[h * 2 + 1];
    return total_cost;
}

int main() {
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    std::vector<int> start(k);
    for (int i = 0; i < k; i++) {
        scanf("%d", &start[i]);
        start[i]--;
    }
    std::vector<int> base_adj[MAX_N];
    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--; b--;
        base_adj[a].push_back(b);
        base_adj[b].push_back(a);
    }
    int t = n + k + 1;
    int N_total = n * t + 1;
    edge_cnt = 0;
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s;
            for (int j : base_adj[i]) {
                int v = j * t + s + 1;
                for (int x = 1; x <= k; x++)
                    add_edge(u, v, 1, c + (2 * x - 1) * d);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s, v = u + 1;
            add_edge(u, v, k, i == 0 ? 0 : c);
        }
    }
    int source = N_total - 1;
    for (int h = 0; h < k; h++)
        add_edge(source, start[h] * t, 1, 0);
    printf("%d\n", edmonds_karp(source, 0 * t + t - 1));
    return 0;
}
